WITH valid_departments AS (SELECT * FROM departments WHERE dept_name IN ('Engineering', 'HR', 'Marketing') AND dept_name IN ('Sales', 'HR', 'Legal')), departments_stats AS (SELECT CASE WHEN budget >= 3755000 THEN 'high' WHEN budget >= 602000 THEN 'mid' ELSE 'low' END AS budget_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(location))) AS location_values, ROUND(AVG(budget), 2) AS avg_budget FROM valid_departments GROUP BY CASE WHEN budget >= 3755000 THEN 'high' WHEN budget >= 602000 THEN 'mid' ELSE 'low' END) SELECT * FROM departments_stats WHERE avg_budget > 57;
